import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import api from '../utils/api';

interface User {
  id: string;
  pseudonym: string;
}

interface Connection {
  id: string;
  creatorId: string;
  recipientId: string;
  relationshipType: string;
  status: 'pending' | 'active' | 'declined';
  createdAt: string;
  updatedAt: string;
  creator: User;
  recipient: User;
}

interface ConnectionState {
  connections: Connection[];
  loading: boolean;
  error: string | null;
  searchResults: User[];
  searchLoading: boolean;
}

const initialState: ConnectionState = {
  connections: [],
  loading: false,
  error: null,
  searchResults: [],
  searchLoading: false,
};

// Fetch all connections
export const fetchConnections = createAsyncThunk('connections/fetchConnections', async (_, { rejectWithValue }) => {
  try {
    const response = await api.get('/connections');
    return response.data;
  } catch (error: any) {
    return rejectWithValue(error.response?.data?.message || 'Failed to fetch connections');
  }
});

// Invite a user to connect
export const inviteConnection = createAsyncThunk(
  'connections/inviteConnection',
  async (
    { recipientPseudonym, relationshipType }: { recipientPseudonym: string; relationshipType: string },
    { rejectWithValue }
  ) => {
    try {
      const response = await api.post('/connections/invite', {
        recipientPseudonym,
        relationshipType,
      });
      return response.data;
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'Failed to send invitation');
    }
  }
);

// Accept a connection invitation
export const acceptConnection = createAsyncThunk(
  'connections/acceptConnection',
  async (connectionId: string, { rejectWithValue }) => {
    try {
      const response = await api.put(`/connections/${connectionId}/accept`);
      return response.data;
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'Failed to accept invitation');
    }
  }
);

// Decline a connection invitation
export const declineConnection = createAsyncThunk(
  'connections/declineConnection',
  async (connectionId: string, { rejectWithValue }) => {
    try {
      const response = await api.put(`/connections/${connectionId}/decline`);
      return response.data;
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'Failed to decline invitation');
    }
  }
);

// Remove a connection
export const removeConnection = createAsyncThunk(
  'connections/removeConnection',
  async (connectionId: string, { rejectWithValue }) => {
    try {
      await api.delete(`/connections/${connectionId}`);
      return connectionId;
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'Failed to remove connection');
    }
  }
);

// Search for users
export const searchUsers = createAsyncThunk(
  'connections/searchUsers',
  async (query: string, { rejectWithValue }) => {
    try {
      const response = await api.get(`/users/search?query=${query}`);
      return response.data;
    } catch (error: any) {
      return rejectWithValue(error.response?.data?.message || 'Failed to search users');
    }
  }
);

const connectionSlice = createSlice({
  name: 'connections',
  initialState,
  reducers: {
    clearConnectionError: (state) => {
      state.error = null;
    },
    clearSearchResults: (state) => {
      state.searchResults = [];
    },
  },
  extraReducers: (builder) => {
    builder
      // Fetch connections
      .addCase(fetchConnections.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchConnections.fulfilled, (state, action: PayloadAction<Connection[]>) => {
        state.connections = action.payload;
        state.loading = false;
      })
      .addCase(fetchConnections.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      })
      // Invite connection
      .addCase(inviteConnection.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(inviteConnection.fulfilled, (state, action: PayloadAction<Connection>) => {
        state.connections.push(action.payload);
        state.loading = false;
      })
      .addCase(inviteConnection.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      })
      // Accept connection
      .addCase(acceptConnection.fulfilled, (state, action: PayloadAction<Connection>) => {
        const index = state.connections.findIndex((conn) => conn.id === action.payload.id);
        if (index !== -1) {
          state.connections[index] = action.payload;
        }
      })
      .addCase(acceptConnection.rejected, (state, action) => {
        state.error = action.payload as string;
      })
      // Decline connection
      .addCase(declineConnection.fulfilled, (state, action: PayloadAction<Connection>) => {
        const index = state.connections.findIndex((conn) => conn.id === action.payload.id);
        if (index !== -1) {
          state.connections[index] = action.payload;
        }
      })
      .addCase(declineConnection.rejected, (state, action) => {
        state.error = action.payload as string;
      })
      // Remove connection
      .addCase(removeConnection.fulfilled, (state, action: PayloadAction<string>) => {
        state.connections = state.connections.filter((conn) => conn.id !== action.payload);
      })
      .addCase(removeConnection.rejected, (state, action) => {
        state.error = action.payload as string;
      })
      // Search users
      .addCase(searchUsers.pending, (state) => {
        state.searchLoading = true;
      })
      .addCase(searchUsers.fulfilled, (state, action: PayloadAction<User[]>) => {
        state.searchResults = action.payload;
        state.searchLoading = false;
      })
      .addCase(searchUsers.rejected, (state) => {
        state.searchResults = [];
        state.searchLoading = false;
      });
  },
});

export const { clearConnectionError, clearSearchResults } = connectionSlice.actions;
export default connectionSlice.reducer;
